namespace ghidra.pcode.exec;



/**
 * A p-code userop library composed of other libraries
 * 
 * @param <T> the type of values processed by the library
 */
public class ComposedPcodeUseropLibrary<T> : PcodeUseropLibrary<T> {
	/**
	 * Obtain a map representing the composition of userops from all the given libraries
	 * 
	 * <p>
	 * Name collisions are not allowed. If any two libraries export the same symbol, even if the
	 * definitions happen to do the same thing, it is an error.
	 * 
	 * @param <T> the type of values processed by the libraries
	 * @param libraries the libraries whose userops to collect
	 * @param override allow libraries to the right to override userops from libraries to the left
	 * @return the resulting map
	 */public static Map<string, PcodeUseropDefinition<T>> composeUserops<T>(
			Collection<PcodeUseropLibrary<T>> libraries, bool @override) {
		Map<string, PcodeUseropDefinition<T>> userops = new();
		foreach (PcodeUseropLibrary<T> lib in libraries) {
			foreach (PcodeUseropDefinition<T> def in lib.getUserops().values()) {
				if (userops.put(def.getName(), def) != null && !override) {
					throw new IllegalArgumentException(
						"Cannot compose libraries with conflicting definitions on " +
							def.getName());
				}
			}
		}
		return Collections.unmodifiableMap(userops);
	}

	private Map<string, PcodeUseropDefinition<T>> userops;

	/**
	 * Construct a composed userop library from the given libraries
	 * 
	 * <p>
	 * This uses {@link #composeUserops(Collection, boolean)}, so its restrictions apply here, too.
	 * 
	 * @param override allow libraries to the right to override userops from libraries to the left
	 * @param libraries the libraries
	 */
	public ComposedPcodeUseropLibrary(Collection<PcodeUseropLibrary<T>> libraries,
			bool @override) {
		this.userops = composeUserops(libraries,@override);
	}

	/* @Override */
	public Map<string, PcodeUseropDefinition<T>> getUserops() {
		return userops;
	}
}
